tape( 'the function supports no prepend and no append', opts, function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;
	var o;

	x = new Complex128Array([
		1.0,
		-1.0,
		3.0,
		-3.0,
		6.0,
		-6.0,
		10.0,
		-10.0
	]);
	p = new Complex128Array( 0 );
	a = new Complex128Array( 0 );
	o = new Complex128Array( 3 );

	out = zediff( x.length, x, 1, 0, p, 1, 0, a, 1, o, 1 );

	expected = new Complex128Array([
		2.0,
		-2.0,
		3.0,
		-3.0,
		4.0,
		-4.0
	]);
	t.strictEqual( isSameComplex128Array( o, expected ), true, 'returns expected value' );
	t.strictEqual( out, o, 'returns expected value' );

	t.end();
});

tape( 'the function supports multiple prepend and append values', opts, function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;
	var o;

	// Multiple prepend (N1=2), no append:
	x = new Complex128Array([
		6.0,
		-6.0,
		8.0,
		-8.0
	]);
	p = new Complex128Array([
		1.0,
		-1.0,
		3.0,
		-3.0
	]);
	a = new Complex128Array( 0 );
	o = new Complex128Array( 3 );

	out = zediff( x.length, x, 1, 2, p, 1, 0, a, 1, o, 1 );

	expected = new Complex128Array([
		1.0,
		-1.0,
		3.0,
		-3.0,
		2.0,
		-2.0
	]);
	t.strictEqual( isSameComplex128Array( o, expected ), true, 'returns expected value' );
	t.strictEqual( out, o, 'returns expected value' );

	// Prepend (N1=1), x, and multiple append (N2=2):
	x = new Complex128Array([
		2.0,
		-2.0,
		4.0,
		-4.0
	]);
	p = new Complex128Array([
		1.0,
		-1.0
	]);
	a = new Complex128Array([
		6.0,
		-6.0,
		10.0,
		-10.0
	]);
	o = new Complex128Array( 4 );

	out = zediff( x.length, x, 1, 1, p, 1, 2, a, 1, o, 1 );

	expected = new Complex128Array([
		1.0,
		-1.0,
		2.0,
		-2.0,
		6.0,
		-6.0,
		10.0,
		-10.0
	]);
	t.strictEqual( isSameComplex128Array( o, expected ), true, 'returns expected value' );
	t.strictEqual( out, o, 'returns expected value' );

	t.end();
});

tape( 'the function supports append without prepend', opts, function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;
	var o;

	// No prepend, x present, single append:
	x = new Complex128Array([
		2.0,
		-2.0,
		5.0,
		-5.0
	]);
	p = new Complex128Array( 0 );
	a = new Complex128Array([
		10.0,
		-10.0
	]);
	o = new Complex128Array( 2 );

	out = zediff( x.length, x, 1, 0, p, 1, 1, a, 1, o, 1 );

	expected = new Complex128Array([
		3.0,
		-3.0,
		10.0,
		-10.0
	]);
	t.strictEqual( isSameComplex128Array( o, expected ), true, 'returns expected value' );
	t.strictEqual( out, o, 'returns expected value' );

	t.end();
});
